'use client';

/*
 * Consent banner, "zeste" style — generated by `zeste add`, yours to edit.
 * Colors: ./theme.css. "Deny all" and "Accept all" deliberately have
 * exactly the same style (EU consent rules: equal prominence).
 */
import { ConsentBanner, useZeste } from '@zeste/react';
import type { Messages } from '@zeste/services/i18n/types';
import './theme.css';

const button =
  'inline-flex items-center justify-center rounded-full border-[1.5px] border-(--zeste-ink) bg-(--zeste-ink) px-[18px] py-2.5 text-sm font-semibold text-(--zeste-paper) transition hover:opacity-90 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-(--zeste-ink)';
const link =
  'rounded-sm text-sm font-semibold text-(--zeste-ink) underline decoration-(--zeste-accent) decoration-[3px] underline-offset-4 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-(--zeste-ink)';

export function CookieBanner() {
  const zeste = useZeste<Messages>();
  const t = zeste.messages;

  return (
    <>
      {zeste.needsReload && (
        // An already-loaded script was refused: it only really stops on reload.
        <div
          role="status"
          data-zeste-skin="zeste"
          className="fixed top-4 right-4 z-50 rounded-2xl border border-(--zeste-line) bg-(--zeste-paper) p-3 shadow-lg"
        >
          <button type="button" className={button} onClick={() => location.reload()}>
            {t.reload}
          </button>
        </div>
      )}

      <ConsentBanner
        data-zeste-skin="zeste"
        aria-label={t.icon}
        className="fixed inset-x-4 bottom-4 z-50 grid max-w-xl gap-3.5 rounded-[20px] border border-(--zeste-line) bg-(--zeste-paper) p-5 text-(--zeste-ink) shadow-[0_18px_50px_rgb(24_48_31/0.22)] sm:right-auto"
      >
        <div className="flex items-center gap-2.5 font-bold">
          {/* Citrus wedge */}
          <svg width="26" height="26" viewBox="0 0 26 26" aria-hidden="true" className="shrink-0">
            <circle cx="13" cy="13" r="12" style={{ fill: 'var(--zeste-accent)', stroke: 'var(--zeste-ink)' }} strokeWidth="1.5" />
            <g style={{ stroke: 'var(--zeste-ink)' }} strokeWidth="1.2">
              <line x1="13" y1="3" x2="13" y2="23" />
              <line x1="3" y1="13" x2="23" y2="13" />
              <line x1="6" y1="6" x2="20" y2="20" />
              <line x1="20" y1="6" x2="6" y2="20" />
            </g>
            <circle cx="13" cy="13" r="2.2" style={{ fill: 'var(--zeste-paper)' }} />
          </svg>
          {t.icon}
        </div>
        <p className="text-[15px] leading-relaxed text-(--zeste-soft)">{t.alertBigPrivacy}</p>
        <div className="flex flex-wrap items-center gap-2">
          <button type="button" className={button} {...zeste.actions.denyAll}>
            {t.denyAll}
          </button>
          <button type="button" className={button} {...zeste.actions.acceptAll}>
            {t.acceptAll}
          </button>
          <button type="button" className={`${link} ml-auto`} {...zeste.actions.openPreferences}>
            {t.personalize}
          </button>
        </div>
      </ConsentBanner>
    </>
  );
}
